/**
 * public/js/teambuilder-engine.js
 * Alpine.js component for the Nuzlox teambuilder page.
 *
 * Validation data is loaded from /cache/ruleset-validator.json (generated by
 * scripts/generate-ruleset-cache.js and refreshed on every ruleset publish).
 *
 * Pokémon list is loaded from /cache/pokemon-list.json.
 * Full Pokémon data and move details are fetched via the server-side PokéAPI proxy:
 *   GET /api/v1/pokeapi/pokemon/:name
 *   GET /api/v1/pokeapi/move/:name
 *
 * Teams are persisted to localStorage for guests (key: nuzlox:teambuilder:v1)
 * and POSTed to /api/v1/teams for authenticated users.
 *
 * @ref wallbreaker/docs/accessibility/APXpatterns/challenge-patterns.md — Safe Practice Zone
 * @ref wallbreaker/docs/accessibility/WCAG/02-operable.md §2.5.7 (keyboard alternative)
 * @ref wallbreaker/docs/accessibility/WCAG/04-robust.md §4.1.3 (live region for validation)
 */

'use strict';

/* ─── Constants ─────────────────────────────────────────────────────────────── */

const LS_KEY = 'nuzlox:teambuilder:v1';

/**
 * Build an empty slot object.
 * @returns {{ species: null, sprite: null, types: [], moves: [null,null,null,null],
 *             held_item: string, nickname: string, violations: [], pokemonData: null, loading: boolean }}
 */
function emptySlot() {
  return {
    species: null,
    sprite: null,
    types: [],
    moves: [null, null, null, null],
    held_item: '',
    nickname: '',
    violations: [],
    pokemonData: null,
    loading: false,
  };
}

/* ─── Alpine.js component ────────────────────────────────────────────────────── */

/**
 * teambuilder()
 * Main Alpine.js data factory for the teambuilder page.
 * Registered globally so the EJS template can call x-data="teambuilder()".
 */
function teambuilder() {
  return {

    /* ── Team state ── */

    /** @type {Array<ReturnType<emptySlot>>} Six slot objects */
    team: Array.from({ length: 6 }, emptySlot),

    /** @type {string} User-supplied name for the team */
    teamName: '',

    /** @type {string} Feedback message shown after a save attempt */
    saveStatus: '',

    /** @type {string[]} Team-level violation strings */
    violations: [],

    /** @type {string[]} Team-level warning strings */
    warnings: [],

    /* ── Pokémon picker ── */

    /** @type {boolean} Whether the Pokémon picker modal is open */
    pickerOpen: false,

    /** @type {number|null} Slot index currently being edited */
    activeSlotIndex: null,

    /** @type {string} Live search query for the Pokémon picker */
    search: '',

    /** @type {Array} Full Pokémon list loaded from /cache/pokemon-list.json */
    pokemonList: [],

    /** @type {Array} Currently displayed (filtered) Pokémon list */
    filteredPokemon: [],

    /* ── Move picker ── */

    /** @type {boolean} Whether the move picker modal is open */
    movePickerOpen: false,

    /** @type {{ slotIdx: number, moveIdx: number }|null} Current move picker target */
    movePickerTarget: null,

    /** @type {string} Live search query for the move picker */
    moveSearch: '',

    /**
     * Full move pool for the Pokémon in the active slot (fetched from PokéAPI).
     * @type {Array<{ name: string, displayName: string, type: string, damage_class: string,
     *                power: number|null, accuracy: number|null, pp: number|null, isForbidden: boolean }>}
     */
    allMoves: [],

    /** @type {Array} Currently displayed (filtered) move list */
    filteredMoves: [],

    /** @type {boolean} True while move pool is being fetched */
    loadingMoves: false,

    /* ── Ruleset / cache ── */

    /** @type {object|null} Parsed ruleset-validator.json */
    ruleset: null,

    /* ── Saved teams ── */

    /** @type {Array} Saved teams loaded from window.__TEAMBUILDER_CONFIG__.savedTeams */
    savedTeams: [],

    /* ───────────────────────────────────────────────────────────────────────
     * Computed-style getters
     * Alpine.js evaluates getters defined on the object lazily.
     * ─────────────────────────────────────────────────────────────────────── */

    /**
     * True when every filled slot has no violations AND at least one slot is filled.
     * @returns {boolean}
     */
    get isValid() {
      if (!this.hasTeam) return false;
      return this.violations.length === 0;
    },

    /**
     * True when at least one slot has a species assigned.
     * @returns {boolean}
     */
    get hasTeam() {
      return this.team.some(s => s.species !== null);
    },

    /* ───────────────────────────────────────────────────────────────────────
     * Lifecycle
     * ─────────────────────────────────────────────────────────────────────── */

    /**
     * Alpine init — called automatically via x-init="init()".
     * Load ruleset, Pokémon list, saved teams, and restore from localStorage.
     */
    async init() {
      const config = window.__TEAMBUILDER_CONFIG__ || {};
      this.savedTeams = config.savedTeams || [];

      /* Load Pokémon list */
      try {
        const res = await fetch('/cache/pokemon-list.json');
        if (res.ok) {
          this.pokemonList = await res.json();
        }
      } catch (e) {
        console.warn('[teambuilder] Could not load pokemon-list.json:', e);
      }

      /* Load ruleset */
      try {
        const res = await fetch('/cache/ruleset-validator.json');
        if (res.ok) {
          this.ruleset = await res.json();
        }
      } catch (e) {
        console.warn('[teambuilder] Could not load ruleset-validator.json:', e);
      }

      /* Build initial filteredPokemon with isForbidden computed */
      this.filteredPokemon = this._computeFilteredPokemon(this.pokemonList);

      /* Restore from localStorage if available */
      this._restoreFromLocalStorage();

      /* Run validation on restored state */
      this.validateTeam();
    },

    /* ───────────────────────────────────────────────────────────────────────
     * Pokémon picker
     * ─────────────────────────────────────────────────────────────────────── */

    /**
     * Open the Pokémon picker for the given slot index.
     * @param {number} index - Slot index (0–5)
     */
    openPicker(index) {
      this.activeSlotIndex = index;
      this.search = '';
      this.filteredPokemon = this._computeFilteredPokemon(this.pokemonList);
      this.pickerOpen = true;
    },

    /** Close the Pokémon picker without making a selection. */
    closePicker() {
      this.pickerOpen = false;
      this.activeSlotIndex = null;
    },

    /**
     * Filter filteredPokemon based on the current search string.
     * Matches against name and types.
     */
    filterPokemon() {
      this.filteredPokemon = this._computeFilteredPokemon(
        this.pokemonList,
        this.search
      );
    },

    /**
     * Internal: compute filtered + annotated pokemon list.
     * @param {Array} list - Raw pokemon list
     * @param {string} [query=''] - Search query
     * @returns {Array}
     */
    _computeFilteredPokemon(list, query) {
      const q = (query || '').toLowerCase().trim();
      return list
        .filter(p => {
          if (!q) return true;
          const nameMatch = (p.name || '').toLowerCase().includes(q) ||
                            (p.displayName || '').toLowerCase().includes(q);
          const typeMatch = (p.types || []).some(t => t.toLowerCase().includes(q));
          return nameMatch || typeMatch;
        })
        .map(p => ({
          id: p.id,
          name: p.name,
          displayName: p.displayName || p.name,
          types: p.types || [],
          sprite: p.sprite || null,
          is_legendary: !!p.is_legendary,
          is_mythical: !!p.is_mythical,
          is_fossil: !!p.is_fossil,
          isForbidden: this._isPokemonForbidden(p),
        }));
    },

    /**
     * Select a Pokémon from the picker.
     * Fetches full PokéAPI data via the server proxy, populates the slot,
     * then closes the picker and validates.
     * @param {{ id: number, name: string, isForbidden: boolean }} p
     */
    async selectPokemon(p) {
      if (this.activeSlotIndex === null) return;

      const idx = this.activeSlotIndex;
      this.closePicker();

      /* Reset the slot to a fresh empty state with loading indicator */
      const slot = emptySlot();
      slot.species = p.name;
      slot.sprite = p.sprite || null;
      slot.types = p.types ? [...p.types] : [];
      slot.loading = true;
      this.team[idx] = slot;
      /* Trigger Alpine reactivity for the array mutation */
      this.team = [...this.team];

      /* Fetch full data from server proxy */
      try {
        const res = await fetch(`/api/v1/pokeapi/pokemon/${encodeURIComponent(p.name)}`);
        if (res.ok) {
          const data = await res.json();
          const updated = {
            ...this.team[idx],
            species: data.name || p.name,
            sprite: data.sprite || p.sprite || null,
            types: data.types ? [...data.types] : slot.types,
            pokemonData: data,
            loading: false,
          };
          this.team[idx] = updated;
          this.team = [...this.team];
        } else {
          this.team[idx] = { ...this.team[idx], loading: false };
          this.team = [...this.team];
        }
      } catch (e) {
        console.warn('[teambuilder] PokéAPI fetch failed for', p.name, e);
        this.team[idx] = { ...this.team[idx], loading: false };
        this.team = [...this.team];
      }

      this.validateTeam();
      this._persistToLocalStorage();
    },

    /**
     * Clear a slot back to its empty state.
     * @param {number} index - Slot index (0–5)
     */
    clearSlot(index) {
      this.team[index] = emptySlot();
      this.team = [...this.team];
      this.validateTeam();
      this._persistToLocalStorage();
    },

    /* ───────────────────────────────────────────────────────────────────────
     * Move picker
     * ─────────────────────────────────────────────────────────────────────── */

    /**
     * Open the move picker for the given slot and move index.
     * Fetches the Pokémon's move pool from the cached PokéAPI proxy.
     * @param {number} slotIdx - Slot index (0–5)
     * @param {number} moveIdx - Move index (0–3)
     */
    async openMovePicker(slotIdx, moveIdx) {
      const slot = this.team[slotIdx];
      if (!slot || !slot.species) return;

      this.movePickerTarget = { slotIdx, moveIdx };
      this.moveSearch = '';
      this.allMoves = [];
      this.filteredMoves = [];
      this.loadingMoves = true;
      this.movePickerOpen = true;

      try {
        const res = await fetch(
          `/api/v1/pokeapi/pokemon/${encodeURIComponent(slot.species)}`
        );
        if (res.ok) {
          const data = await res.json();
          const rawMoves = (data.moves || []).map(m => ({
            name: m.name || m,
            displayName: m.displayName || this._toDisplayName(m.name || m),
            type: m.type || null,
            damage_class: m.damage_class || null,
            power: m.power != null ? m.power : null,
            accuracy: m.accuracy != null ? m.accuracy : null,
            pp: m.pp != null ? m.pp : null,
            secondary_status: m.secondary_status || null,
            secondary_volatile: m.secondary_volatile || null,
            secondary_chance: m.secondary_chance || null,
            secondary_boosts: m.secondary_boosts || null,
            isForbidden: this._isMoveForbidden(m.name || m, m.type || null, m),
          }));
          this.allMoves = rawMoves;
          this.filteredMoves = rawMoves;
        }
      } catch (e) {
        console.warn('[teambuilder] Could not load move pool for', slot.species, e);
      } finally {
        this.loadingMoves = false;
      }
    },

    /** Close the move picker without making a selection. */
    closeMovePicker() {
      this.movePickerOpen = false;
      this.movePickerTarget = null;
      this.moveSearch = '';
    },

    /**
     * Filter filteredMoves based on moveSearch.
     */
    filterMoves() {
      const q = (this.moveSearch || '').toLowerCase().trim();
      if (!q) {
        this.filteredMoves = this.allMoves;
        return;
      }
      this.filteredMoves = this.allMoves.filter(m => {
        const nameMatch = m.name.toLowerCase().includes(q) ||
                          m.displayName.toLowerCase().includes(q);
        const typeMatch = m.type && m.type.toLowerCase().includes(q);
        const classMatch = m.damage_class && m.damage_class.toLowerCase().includes(q);
        return nameMatch || typeMatch || classMatch;
      });
    },

    /**
     * Select a move from the move picker.
     * Fetches full move details from /api/v1/pokeapi/move/:name, writes to the slot.
     * @param {{ name: string, displayName: string, isForbidden: boolean }} move
     */
    async selectMove(move) {
      if (!this.movePickerTarget) return;
      const { slotIdx, moveIdx } = this.movePickerTarget;
      this.closeMovePicker();

      /* Optimistically set move name while fetching details */
      const newMoves = [...this.team[slotIdx].moves];
      newMoves[moveIdx] = {
        name: move.name,
        displayName: move.displayName,
        type: move.type,
        damage_class: move.damage_class,
        power: move.power,
        accuracy: move.accuracy,
        pp: move.pp,
        isForbidden: move.isForbidden,
      };
      this.team[slotIdx] = { ...this.team[slotIdx], moves: newMoves };
      this.team = [...this.team];

      /* Fetch full move details */
      try {
        const res = await fetch(
          `/api/v1/pokeapi/move/${encodeURIComponent(move.name)}`
        );
        if (res.ok) {
          const detail = await res.json();
          const enrichedMoves = [...this.team[slotIdx].moves];
          enrichedMoves[moveIdx] = {
            name: detail.name || move.name,
            displayName: detail.displayName || move.displayName,
            type: detail.type || move.type,
            damage_class: detail.damage_class || move.damage_class,
            power: detail.power != null ? detail.power : move.power,
            accuracy: detail.accuracy != null ? detail.accuracy : move.accuracy,
            pp: detail.pp != null ? detail.pp : move.pp,
            effect: detail.effect || null,
            secondary_status: detail.secondary_status ?? move.secondary_status ?? null,
            secondary_volatile: detail.secondary_volatile ?? move.secondary_volatile ?? null,
            secondary_chance: detail.secondary_chance ?? move.secondary_chance ?? null,
            secondary_boosts: detail.secondary_boosts ?? move.secondary_boosts ?? null,
            isForbidden: this._isMoveForbidden(
              detail.name || move.name,
              detail.type || move.type,
              detail
            ),
          };
          this.team[slotIdx] = { ...this.team[slotIdx], moves: enrichedMoves };
          this.team = [...this.team];
        }
      } catch (e) {
        console.warn('[teambuilder] Could not fetch move details for', move.name, e);
      }

      this.validateTeam();
      this._persistToLocalStorage();
    },

    /**
     * Clear the move at the current movePickerTarget.
     */
    clearMove() {
      if (!this.movePickerTarget) return;
      const { slotIdx, moveIdx } = this.movePickerTarget;
      const newMoves = [...this.team[slotIdx].moves];
      newMoves[moveIdx] = null;
      this.team[slotIdx] = { ...this.team[slotIdx], moves: newMoves };
      this.team = [...this.team];
      this.closeMovePicker();
      this.validateTeam();
      this._persistToLocalStorage();
    },

    /* ───────────────────────────────────────────────────────────────────────
     * Validation
     * ─────────────────────────────────────────────────────────────────────── */

    /**
     * Validate the current team against the loaded ruleset.
     * Updates slot.violations for each slot, plus this.violations and this.warnings.
     */
    validateTeam() {
      const teamViolations = [];
      const teamWarnings = [];

      if (!this.ruleset) {
        /* Ruleset not yet loaded — clear all slot violations */
        this.team.forEach(slot => { slot.violations = []; });
        this.violations = [];
        this.warnings = [];
        return;
      }

      const {
        forbidden_types = [],
        forbidden_species_categories = [],
        forbidden_moves = [],
        forbidden_move_categories = [],
        forbidden_items = [],
        restricted_types = {},
        forbidden_secondary_effects = [],
      } = this.ruleset;
      const normalizeMoveName = n => (n || '').toLowerCase().replace(/-/g, '');
      const normalizedForbiddenMoves = forbidden_moves.map(normalizeMoveName);
      const secondaryEffectSet = new Set(forbidden_secondary_effects);

      const updatedTeam = this.team.map(slot => {
        const slotViolations = [];

        if (!slot.species) {
          return { ...slot, violations: [] };
        }

        const speciesLabel = slot.nickname
          ? `${slot.nickname} (${slot.species})`
          : slot.species;

        /* Forbidden types */
        const forbiddenTypeHits = (slot.types || []).filter(
          t => forbidden_types.includes(t.toLowerCase())
        );
        if (forbiddenTypeHits.length) {
          slotViolations.push(
            `${speciesLabel}: forbidden type(s) — ${forbiddenTypeHits.join(', ')}`
          );
        }

        /* Forbidden species categories (legendary, mythical, fossil) */
        const pkData = slot.pokemonData || {};
        if (
          forbidden_species_categories.includes('legendary') && pkData.is_legendary
        ) {
          slotViolations.push(`${speciesLabel}: legendaries are forbidden`);
        }
        if (
          forbidden_species_categories.includes('mythical') && pkData.is_mythical
        ) {
          slotViolations.push(`${speciesLabel}: mythicals are forbidden`);
        }
        if (
          forbidden_species_categories.includes('fossil') && pkData.is_fossil
        ) {
          slotViolations.push(`${speciesLabel}: fossil Pokémon are forbidden`);
        }

        /* Breeding check */
        if (pkData.can_breed === false) {
          teamWarnings.push(
            `${speciesLabel}: cannot breed — verify eligibility`
          );
        }

        /* Move checks */
        for (const move of (slot.moves || [])) {
          if (!move) continue;

          const moveName = normalizeMoveName(move.name || '');
          const moveType = (move.type || '').toLowerCase();
          const moveLabel = move.displayName || move.name || moveName;

          /* Forbidden moves by slug */
          if (normalizedForbiddenMoves.includes(moveName)) {
            slotViolations.push(
              `${speciesLabel}: forbidden move — ${moveLabel}`
            );
          }

          /* Forbidden move types (ghost, dark) */
          if (moveType && forbidden_move_categories.includes(moveType)) {
            slotViolations.push(
              `${speciesLabel}: move of forbidden type (${moveType}) — ${moveLabel}`
            );
          }

          /* Restricted type move checks (psychic, fairy) */
          for (const [restrictedType, ruleObj] of Object.entries(restricted_types || {})) {
            const slotHasType = (slot.types || []).some(
              t => t.toLowerCase() === restrictedType.toLowerCase()
            );
            if (!slotHasType) continue;

            const restrictedMoveForbidden = (ruleObj.forbidden_moves || []).map(normalizeMoveName);
            if (restrictedMoveForbidden.includes(moveName)) {
              slotViolations.push(
                `${speciesLabel}: ${restrictedType}-type Pokémon cannot use ${moveLabel}`
              );
            }
          }

          /* Secondary effect check */
          if (secondaryEffectSet.size) {
            if (move.secondary_status && secondaryEffectSet.has(move.secondary_status)) {
              slotViolations.push(
                `${speciesLabel}: move can inflict ${move.secondary_status} — ${moveLabel}`
              );
            }
            if (move.secondary_volatile && secondaryEffectSet.has(move.secondary_volatile)) {
              slotViolations.push(
                `${speciesLabel}: move can cause ${move.secondary_volatile} — ${moveLabel}`
              );
            }
            if (move.secondary_boosts && Object.values(move.secondary_boosts).some(v => v < 0)) {
              slotViolations.push(
                `${speciesLabel}: move can lower a stat — ${moveLabel}`
              );
            }
          }
        }

        /* Held item check */
        if (slot.held_item && forbidden_items.includes(slot.held_item.toLowerCase())) {
          slotViolations.push(
            `${speciesLabel}: forbidden held item — ${slot.held_item}`
          );
        }

        const uniqueSlotViolations = [...new Set(slotViolations)];
        teamViolations.push(...uniqueSlotViolations);
        return { ...slot, violations: uniqueSlotViolations };
      });

      this.team = updatedTeam;
      this.violations = teamViolations;
      this.warnings = teamWarnings;
    },

    /* ───────────────────────────────────────────────────────────────────────
     * Save / load
     * ─────────────────────────────────────────────────────────────────────── */

    /**
     * POST the current team to /api/v1/teams.
     * Sets saveStatus with user-facing feedback.
     */
    async saveTeam() {
      if (!this.hasTeam) return;
      this.saveStatus = 'Saving…';

      const csrf = document.querySelector('meta[name="csrf-token"]')?.content || '';
      const rulesetVersion = this.ruleset?.version || '1';

      const pokemonPayload = this.team
        .filter(s => s.species)
        .map(s => ({
          species: s.species,
          nickname: s.nickname || '',
          held_item: s.held_item || '',
          moves: (s.moves || []).map(m => (m ? m.name : null)).filter(Boolean),
          types: s.types || [],
          is_bred: !!(s.pokemonData && s.pokemonData.can_breed !== false),
        }));

      const body = {
        team_name: this.teamName || 'My Team',
        pokemon: pokemonPayload,
        ruleset_version: rulesetVersion,
        is_valid: this.isValid,
        violations: this.violations,
      };

      try {
        const res = await fetch('/api/v1/teams', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'X-CSRF-Token': csrf,
          },
          body: JSON.stringify(body),
        });
        const data = await res.json();
        if (!res.ok) throw new Error(data.error || 'Save failed');
        this.saveStatus = 'Team saved!';
        /* Add or update in savedTeams list */
        const existing = this.savedTeams.findIndex(t => t.id === data.id);
        if (existing >= 0) {
          this.savedTeams[existing] = data;
          this.savedTeams = [...this.savedTeams];
        } else {
          this.savedTeams = [...this.savedTeams, data];
        }
      } catch (err) {
        this.saveStatus = `Save failed: ${err.message}`;
      }
    },

    /**
     * Load a saved team object into the team slots.
     * @param {{ team_name: string, pokemon: Array, is_valid: boolean }} t - Saved team object
     */
    loadTeam(t) {
      if (!t || !Array.isArray(t.pokemon)) return;
      this.teamName = t.team_name || '';

      const newTeam = Array.from({ length: 6 }, emptySlot);
      t.pokemon.forEach((p, i) => {
        if (i >= 6) return;
        newTeam[i] = {
          ...emptySlot(),
          species: p.species || null,
          sprite: p.sprite || null,
          types: p.types ? [...p.types] : [],
          nickname: p.nickname || '',
          held_item: p.held_item || '',
          moves: Array.from({ length: 4 }, (_, mi) => {
            const rawMove = (p.moves || [])[mi];
            if (!rawMove) return null;
            if (typeof rawMove === 'string') {
              return {
                name: rawMove,
                displayName: this._toDisplayName(rawMove),
                type: null,
                damage_class: null,
                power: null,
                accuracy: null,
                pp: null,
                isForbidden: this._isMoveForbidden(rawMove, null),
              };
            }
            return rawMove;
          }),
          pokemonData: p.pokemonData || null,
          loading: false,
        };
      });

      this.team = newTeam;
      this.validateTeam();
      this._persistToLocalStorage();
    },

    /* ───────────────────────────────────────────────────────────────────────
     * LocalStorage persistence
     * ─────────────────────────────────────────────────────────────────────── */

    /**
     * Persist the current team and teamName to localStorage.
     * Only called for guest users — auth users rely on the API save.
     */
    _persistToLocalStorage() {
      try {
        const payload = {
          teamName: this.teamName,
          team: this.team.map(s => ({
            species: s.species,
            sprite: s.sprite,
            types: s.types,
            nickname: s.nickname,
            held_item: s.held_item,
            moves: s.moves,
            pokemonData: s.pokemonData,
          })),
        };
        localStorage.setItem(LS_KEY, JSON.stringify(payload));
      } catch (e) {
        /* localStorage unavailable (private browsing quota, etc.) — silent fail */
      }
    },

    /**
     * Restore team from localStorage if a saved state exists.
     */
    _restoreFromLocalStorage() {
      try {
        const raw = localStorage.getItem(LS_KEY);
        if (!raw) return;
        const payload = JSON.parse(raw);
        if (!payload || !Array.isArray(payload.team)) return;

        this.teamName = payload.teamName || '';
        const restored = Array.from({ length: 6 }, emptySlot);
        payload.team.forEach((s, i) => {
          if (i >= 6 || !s) return;
          restored[i] = {
            ...emptySlot(),
            species: s.species || null,
            sprite: s.sprite || null,
            types: s.types ? [...s.types] : [],
            nickname: s.nickname || '',
            held_item: s.held_item || '',
            moves: Array.from({ length: 4 }, (_, mi) => {
              const m = (s.moves || [])[mi];
              return m || null;
            }),
            pokemonData: s.pokemonData || null,
            loading: false,
          };
        });
        this.team = restored;
      } catch (e) {
        /* Corrupt or missing localStorage — start fresh */
        console.warn('[teambuilder] Could not restore from localStorage:', e);
      }
    },

    /* ───────────────────────────────────────────────────────────────────────
     * Internal helpers
     * ─────────────────────────────────────────────────────────────────────── */

    /**
     * Determine if a Pokémon should be marked as forbidden given the current ruleset.
     * @param {{ types?: string[], is_legendary?: boolean, is_mythical?: boolean, is_fossil?: boolean }} p
     * @returns {boolean}
     */
    _isPokemonForbidden(p) {
      if (!this.ruleset) return false;
      const {
        forbidden_types = [],
        forbidden_species_categories = [],
      } = this.ruleset;

      if ((p.types || []).some(t => forbidden_types.includes(t.toLowerCase()))) {
        return true;
      }
      if (forbidden_species_categories.includes('legendary') && p.is_legendary) {
        return true;
      }
      if (forbidden_species_categories.includes('mythical') && p.is_mythical) {
        return true;
      }
      if (forbidden_species_categories.includes('fossil') && p.is_fossil) {
        return true;
      }
      return false;
    },

    /**
     * Determine if a move (by slug name and type) is forbidden.
     * @param {string} moveName - lowercase slug
     * @param {string|null} moveType - lowercase type string or null
     * @returns {boolean}
     */
    _isMoveForbidden(moveName, moveType, moveData) {
      if (!this.ruleset) return false;
      const {
        forbidden_moves = [],
        forbidden_move_categories = [],
        forbidden_secondary_effects = [],
      } = this.ruleset;

      const norm = n => (n || '').toLowerCase().replace(/-/g, '');
      if (forbidden_moves.some(m => norm(m) === norm(moveName))) return true;
      if (moveType && forbidden_move_categories.includes(moveType.toLowerCase())) return true;
      if (forbidden_secondary_effects.length && moveData) {
        const effects = new Set(forbidden_secondary_effects);
        if (moveData.secondary_status && effects.has(moveData.secondary_status)) return true;
        if (moveData.secondary_volatile && effects.has(moveData.secondary_volatile)) return true;
        if (moveData.secondary_boosts &&
            Object.values(moveData.secondary_boosts).some(v => v < 0)) return true;
      }
      return false;
    },

    /**
     * Convert a PokéAPI slug (e.g. "fire-blast") to a display name ("Fire Blast").
     * @param {string} slug
     * @returns {string}
     */
    _toDisplayName(slug) {
      if (!slug) return '';
      return slug
        .split('-')
        .map(word => word.charAt(0).toUpperCase() + word.slice(1))
        .join(' ');
    },

  };
}
